            { id = "hum_inc_1", icon = "hd_plussign_priest", name = "Incremento de caracteristica (+1)", type = "choice", description = "Otra característica de tu elección aumenta en 1.", effects = {}, choice = { slots = 1, optionsFrom = "ability+1" } },
            { id = "hum_determinacion", icon = "ability_warrior_rallyingcry", name = "Determinacion", type = "informativo", description = "Cuando realices una tirada de ataque, una prueba de habilidad o una tirada de salvación, puedes hacerlo con ventaja. No puedes hacerlo de nuevo hasta que termines un descanso corto o largo.", uses = { max = 1, recharge = "long" }, effects = {} },
