                { id = "eln_alt_erudito", icon = "spell_holy_arcaneintellect", name = "Erudito arcano", type = "pasivo", description = "Conoces el truco Mano de mago. A nivel 3 puedes lanzar Detectar magia 1 vez al día; a nivel 5, Identificar 1 vez al día. La característica para estos conjuros es Inteligencia.", spellGrants = { { level = 0, ids = { "mano_de_mago" }, ability = "Inteligencia" }, { level = 1, ids = { "detectar_magia" }, ability = "Inteligencia", minCharacterLevel = 3, note = "1/dia" }, { level = 1, ids = { "identificar" }, ability = "Inteligencia", minCharacterLevel = 5, note = "1/dia" } }, effects = {} },
