        traits = {
            { id = "eln_vision", icon = "eps_bg3_darkvision", name = "Vision en la oscuridad superior", type = "pasivo", description = "Puedes ver en penumbra hasta 36 metros como luz brillante y en oscuridad como penumbra, todo en un tono violeta.", effects = {} },
            { id = "eln_armas", icon = "inv_sword_1h_warfrontsnightelf_d_01", name = "Entrenamiento con armas Kaldorei", type = "pasivo", description = "Competencia con arco largo, espada lunar, glaive lunar y glaive de guerra.", effects = WeaponProfEffects("arco largo", "espada lunar", "glaive lunar", "glaive de guerra") },
            { id = "eln_idiomas", icon = "inv_misc_note_05", name = "Idiomas", type = "informativo", description = "Hablas, lees y escribes Común y Darnassiano. Este idioma es fluido y complejo, con canciones y poemas famosos entre otras razas.", effects = { { kind = "language", language = "Comun" }, { kind = "language", language = "Darnassiano" } } },
