                { id = "dra_fl_juicio", icon = "ability_paladin_toweroflight", name = "Juicio de la Luz", type = "pasivo", description = "Conoces el truco *luz*. Al alcanzar el nivel 3, puedes lanzar *rayo guiador* una vez por descanso largo. Al nivel 5, puedes lanzar *golpe de marca* una vez por descanso largo. Sabiduría es tu habilidad para lanzar estos hechizos.", spellGrants = { { level = 0, ids = { "luz" }, ability = "Sabiduria" }, { level = 1, ids = { "saeta_guiada" }, ability = "Sabiduria", minCharacterLevel = 3, note = "1/descanso largo" }, { level = 2, ids = { "castigo_marcador" }, ability = "Sabiduria", minCharacterLevel = 5, note = "1/descanso largo" } }, effects = {} },
