            { id = "raza_draenei_tabido", name = "Draenei Tabido", nameF = "Draenei Tábida", desc = "Draenei rotos por la energía vil; marginados pero resistentes y perseverantes.\n\nTu conexión con los Naaru fue cortada en Draenor, dejándote como un reflejo vacío de tu pueblo. Esta separación te ha desfigurado, haciéndote un paria entre los draenei del Exodar y los forjados por la luz.", summary = "Draenei afectado por una degeneración física causada por energías corruptoras, apartado durante mucho tiempo de la sociedad draenei pese a conservar su voluntad.", traits = {
                { id = "dra_tab_inc", icon = "hd_plussign_monk", name = "Incremento de caracteristica", type = "pasivo", description = "Sabiduría +1.", effects = { { kind = "bonus", target = "ability", ability = "Sabiduria", value = 1 } } },
                { id = "dra_tab_vision", icon = "eps_bg3_darkvision", name = "Vision en la oscuridad", type = "pasivo", description = "Tienes visión en la penumbra hasta 18 metros como si fuera luz brillante y en oscuridad como penumbra. Solo puedes ver en tonos de gris.", effects = {} },
                { id = "dra_tab_elemental", icon = "spell_nature_elementalprecision_1", name = "Vinculo elemental", type = "pasivo", description = "Conoces el truco *escarcha*. Al nivel 3, puedes lanzar *temblor de tierra* una vez por descanso largo. Al nivel 5, puedes lanzar *ráfaga de viento* una vez por descanso largo. Sabiduría es tu habilidad para lanzar estos hechizos.", spellGrants = { { level = 0, ids = { "mordedura_helada" }, ability = "Sabiduria" }, { level = 1, ids = { "temblor_de_tierra" }, ability = "Sabiduria", minCharacterLevel = 3, note = "1/descanso largo" }, { level = 2, ids = { "rafaga_de_viento" }, ability = "Sabiduria", minCharacterLevel = 5, note = "1/descanso largo" } }, effects = {} },
                { id = "dra_tab_paria", icon = "eps_wc3_brokendraenei", name = "Paria", type = "pasivo", description = "Competencia en Supervivencia.", effects = { { kind = "skillProf", skill = "Supervivencia" } } },
