            { id = "hua_dos_formas", icon = "eps_wc3h_worgencurse", name = "Dos formas", type = "pasivo", description = "Puedes transformarte en humano en 1 minuto. En esta forma, te ves igual que antes de la maldición. Puedes volver a la forma de huargen como una acción gratuita, y lo harás automáticamente al atacar o lanzar un hechizo ofensivo.", effects = {} },
            { id = "hua_idiomas", icon = "inv_misc_note_05", name = "Idiomas", type = "choice", description = "Hablas, lees y escribes Comun y un idioma adicional de tu elección.", effects = { { kind = "language", language = "Comun" } }, choice = { slots = 1, optionsFrom = "language" } },
