            { id = "raza_orco_guerreros", name = "Clanes Guerreros", desc = "Orcos de los clanes guerreros: brutales y agresivos en la primera línea de batalla.\n\nPrefieren el combate directo. Ejemplos: Grito de Guerra, Hoja Ardiente, Lobo Gélido.", summary = "Clanes orcos como Grito de Guerra, Hoja Ardiente y Lobo Gélido, definidos por una fuerte tradición marcial, tribal y centrada en el combate directo.", traits = {
