        },
        traits = {
            { id = "ren_inc", icon = "hd_plussign_deathknight", name = "Incremento de caracteristica", type = "pasivo", description = "Constitución +2.", effects = { { kind = "bonus", target = "ability", ability = "Constitucion", value = 2 } } },
            { id = "ren_vision", icon = "eps_bg3_darkvision", name = "Vision en la oscuridad", type = "pasivo", description = "Puedes ver en la oscuridad hasta 18 metros como si fuera luz tenue, y en la penumbra como si fuera luz brillante. No puedes distinguir colores, solo tonos de gris.", effects = {} },
            { id = "ren_descanso", icon = "achievement_bg_xkills_avgraveyard", name = "Descanso de la tumba", type = "pasivo", description = "Para obtener los beneficios de un descanso largo, debes realizar al menos seis horas de actividad ligera en lugar de dormir.", effects = {} },
            { id = "ren_naturaleza", icon = "inv_qirajidol_death", name = "Naturaleza no-muerta", type = "pasivo", description = "Tu tipo de criatura es no-muerto en lugar de humanoide y obtienes los siguientes beneficios:\n- Cuentas como humanoide para efectos que no afectan a los no-muertos.\n- Tienes ventaja en tiradas de salvación contra veneno y resistencia al daño por veneno.\n- No necesitas comer, beber ni respirar.\n- No necesitas dormir, y la magia no puede hacerte dormir.", effects = {
