            { id = "ren_idiomas", icon = "inv_misc_note_05", name = "Idiomas", type = "informativo", description = "Hablas, lees y escribes Común y Viscerálico, una forma baja de Común usada en mercados clandestinos.", effects = { { kind = "language", language = "Comun" }, { kind = "language", language = "Visceralico" } } },
