                { id = "tau_tau_tundra", icon = "wh_walkbetweenworlds", name = "Caminante de la tundra", type = "pasivo", description = "Te mueves por terreno difícil de hielo o nieve sin gastar movimiento adicional.", effects = {} },
            } },
