        traits = {
            { id = "tau_inc", icon = "hd_plussign_warrior", name = "Incremento de caracteristica", type = "pasivo", description = "Fuerza +2.", effects = { { kind = "bonus", target = "ability", ability = "Fuerza", value = 2 } } },
            { id = "tau_cuernos", icon = "inv_misc_horn_05", name = "Cuernos", type = "pasivo", description = "Tus cuernos son armas naturales, que puedes usar para realizar ataques desarmados. Si impactas, infliges daño perforante igual a 1d6 + Mod. Fuerza en lugar del daño contundente normal.", effects = {} },
            { id = "tau_construccion", icon = "eps_wc3h_taurenwardrum", name = "Construccion poderosa", type = "pasivo", description = "Cuentas como una categoría de tamaño mayor para determinar tu capacidad de carga y el peso que puedes empujar, arrastrar o levantar.", effects = {} },
            { id = "tau_armas", icon = "inv_archaeology_70_tauren_handsmoothedpyrestone", name = "Entrenamiento de armas Tauren", type = "pasivo", description = "Competencia con alabarda, tótem de batalla, pistola y rifle.", effects = WeaponProfEffects("alabarda", "totem de batalla", "pistolas", "rifles") },
            { id = "tau_idiomas", icon = "inv_misc_note_05", name = "Idiomas", type = "informativo", description = "Puedes hablar, leer y escribir Común y Taur-ahe, un lenguaje fuerte y grave, escrito en pictogramas y formas.", effects = { { kind = "language", language = "Comun" }, { kind = "language", language = "Taur-ahe" } } },
        },
