                { id = "tro_jun_berserker", icon = "racial_troll_berserk", name = "Berserker", type = "informativo", description = "Puedes realizar un ataque con un arma o lanzar un truco con un tiempo de lanzamiento de una acción como acción adicional en tu turno. No puedes volver a usar esta característica hasta que completes un descanso corto o largo.", uses = { max = 1, recharge = "short" }, effects = {} },
                { id = "tro_jun_voodoo", icon = "eps_wc3h_voodoohelm", name = "Da voodoo shuffle", type = "pasivo", description = "Puedes moverte a través de terreno difícil no mágico sin gastar movimiento adicional.", effects = {} },
                { id = "tro_jun_armas", icon = "eps_wc3h_trollishaxe", name = "Entrenamiento con armas Troll", type = "pasivo", description = "Competencia con hachas de mano, hachas de batalla, dagas y jabalinas.", effects = WeaponProfEffects("hacha de mano", "hacha de batalla", "dagas", "jabalinas") },
            } },
            { id = "raza_trol_zandalari", name = "Troll Zandalari", desc = "Trolls del antiguo imperio, orgullosos y devotos de los loa, herederos de una civilización milenaria.\n\nTienes una conexión sin igual con los loas y antiguas tradiciones más antiguas que la mayoría de las razas. Son la raza ancestral de todos los trolls y están en el centro de la unión de trolls en su ciudad templo de Zuldazar en Zandalar. Estos trolls son más poderosos que el resto y poseen una inmensa influencia y respeto entre sus tribus.", summary = "Troll heredero de una antigua civilización imperial, con una cultura sofisticada, una fuerte tradición religiosa y una estrecha relación con los loa.", traits = {
                { id = "tro_zan_inc", icon = "hd_plussign_monk", name = "Incremento de caracteristica", type = "pasivo", description = "Sabiduría +2.", effects = { { kind = "bonus", target = "ability", ability = "Sabiduria", value = 2 } } },
                { id = "tro_zan_conocimiento", icon = "achievements_zone_azsuna", name = "Conocimiento antiguo", type = "pasivo", description = "Competencia en Historia.", effects = { { kind = "skillProf", skill = "Historia" } } },
                { id = "tro_zan_loa", icon = "ability_racial_embraceoftheloa_gonk", name = "Abrazo de los loa", type = "informativo", description = "Conoces el truco *guía*. Cuando alcances el nivel 3, puedes lanzar el conjuro *Potenciar característica* una vez al día usando Sabiduría como habilidad de lanzamiento de conjuros.", uses = { max = 1, recharge = "long" }, effects = {} },
                { id = "tro_zan_armas", icon = "inv_polearm_2h_zandalariguard_b_01", name = "Entrenamiento con armas zandalari", type = "pasivo", description = "Competencia con hachas de mano, hachas de batalla, espadas largas y espadas grandes.", effects = WeaponProfEffects("hacha de mano", "hacha de batalla", "espadas largas", "espadas grandes") },
            } },
            { id = "raza_trol_bosque", name = "Troll de Bosque", desc = "Trolls de bosque amani, feroces y territoriales, ligados a las profundidades arboladas.\n\nTienes un conocimiento agudo del mundo natural, astucia para la guerra y un odio ancestral hacia los humanos y los elfos. Estos trolls son de los que quedan del Imperio Amani, que cayó a manos de la Alianza y la Horda.", summary = "Troll adaptado a regiones boscosas y heredero de culturas como la Amani, con una larga tradición guerrera y una profunda hostilidad histórica hacia los altos elfos.", traits = {
                { id = "tro_bos_inc", icon = "hd_plussign_hunter", name = "Incremento de caracteristica", type = "pasivo", description = "Destreza +1 y Constitución +1.", effects = {
