                { id = "tro_bos_armas", icon = "eps_wc3h_trollishaxe", name = "Entrenamiento con armas Troll", type = "pasivo", description = "Competencia con hachas de mano, hachas de batalla, dagas y jabalinas.", effects = WeaponProfEffects("hacha de mano", "hacha de batalla", "dagas", "jabalinas") },
            } },
            { id = "raza_trol_hielo", name = "Troll de Hielo", desc = "Trolls drakkari de Rasganorte, brutales supervivientes de las tierras heladas.\n\nComo troll de hielo, eres resistente y fuerte, habituado a climas fríos. Estos trolls son bárbaros y brutales, incluso comparados con otros de su especie. Los trolls de hielo viven en condiciones extremas, donde la supervivencia es lo más importante y el más fuerte es quien gobierna.", summary = "Troll adaptado a regiones frías y montañosas, perteneciente a tribus endurecidas por el clima y caracterizadas por su resistencia, aislamiento y tradición guerrera.", traits = {
                { id = "tro_hie_inc", icon = "hd_plussign_warrior", name = "Incremento de caracteristica", type = "pasivo", description = "Fuerza +2.", effects = { { kind = "bonus", target = "ability", ability = "Fuerza", value = 2 } } },
