                { id = "tro_hie_constitucion", icon = "w3reforgedicetrollshaman", name = "Constitucion poderosa", type = "pasivo", description = "Cuentas como una criatura de un tamaño mayor cuando determines tu capacidad de carga y el peso que puedes empujar, arrastrar o levantar.", effects = {} },
                { id = "tro_hie_armas", icon = "eps_wc3h_trollishaxe", name = "Entrenamiento con armas Troll", type = "pasivo", description = "Competencia con hachas de mano, hachas de batalla, dagas y jabalinas.", effects = WeaponProfEffects("hacha de mano", "hacha de batalla", "dagas", "jabalinas") },
