        traits = {
            { id = "tro_inc", icon = "hd_plussign_deathknight", name = "Incremento de caracteristica", type = "pasivo", description = "Constitución +1.", effects = { { kind = "bonus", target = "ability", ability = "Constitucion", value = 1 } } },
            { id = "tro_vision", icon = "eps_bg3_darkvision", name = "Vision en la oscuridad", type = "pasivo", description = "Los trolls conservan su visión en condiciones de poca luz y oscuridad. Puedes ver en luz tenue a 18 metros como si fuera luz brillante y en la oscuridad como si fuera luz tenue. No puedes discernir colores en la oscuridad, solo tonos de gris.", effects = {} },
            { id = "tro_regeneracion", icon = "ability_racial_regeneratin", name = "Regeneracion", type = "pasivo", description = "Siempre que gastes un Dado de Golpe para recuperar puntos de golpe, recuperas puntos de golpe iguales al número lanzado más el doble de Mod. Constitución.\n\nComo acción, puedes gastar un número de Dados de Golpe hasta la mitad de tu nivel, como si hubieras terminado un descanso corto. Debes completar un descanso largo para volver a usar esta característica.", effects = {
