            { id = "esa_vision", icon = "eps_bg3_darkvision", name = "Vision en la oscuridad", type = "pasivo", description = "Puedes ver en luz tenue en un radio de 18 metros como si fuera luz brillante, y en oscuridad como si fuera luz tenue. En la oscuridad, solo puedes distinguir tonos de gris, sin distinguir colores.", effects = {} },
            { id = "esa_arcano", icon = "ability_racial_arcaneaffinity", name = "Conocimiento Arcano", type = "pasivo", description = "Competencia con Conocimiento Arcano y puedes lanzar *detectar magia*, usando Inteligencia como tu habilidad de conjuración. Una vez que lanzas detectar magia, no puedes hacerlo de nuevo hasta un descanso corto o largo.", spellGrants = { { level = 1, ids = { "detectar_magia" }, ability = "Inteligencia", note = "1/dia" } }, effects = { { kind = "skillProf", skill = "Arcano" } } },
            { id = "esa_sentidos", icon = "eps_wc3_nightelfcharm", name = "Sentidos agudos", type = "pasivo", description = "Eres competente en Percepción.", effects = { { kind = "skillProf", skill = "Percepcion" } } },
            { id = "esa_reversion", icon = "eps_bg3_counterspell", name = "Reversion de conjuros", type = "informativo", description = "Cuando fallas una tirada de salvación contra un conjuro o efecto similar, puedes repetir la tirada y debes usar el nuevo resultado. No puedes usar esta característica de nuevo hasta que termines un descanso corto o largo.", uses = { max = 1, recharge = "short" }, effects = {} },
            { id = "esa_legado", name = "Legado thalassiano", type = "choice", description = "Conoces un truco de la lista de mago a tu elección. La Inteligencia es tu característica de lanzamiento para este conjuro. En su lugar puedes ganar competencia con espada gemela, guja, arco corto y arco largo.", effects = {}, choice = {
