            { id = "pan_gourmet", icon = "pandarenracial_gourmand", name = "Gourmet", type = "pasivo", description = "Obtienes competencia con herramientas de artesano (utensilios de cocina) y herramientas de artesano (suministros de cervecería).", effects = {
